"""Serial executable evidence for the approved existing-page documentation pass."""

import hashlib
import json
import os
import re
import subprocess
import tempfile
from pathlib import Path

root = Path.cwd()
audit = root / "target/audit/next-pass"
jar = root / "target/code-tracer.jar"
work = Path(tempfile.mkdtemp(prefix="contract-probes-", dir=audit))
settings = subprocess.run(["java", "-XshowSettings:properties", "-version"], capture_output=True, text=True, check=True)
home = Path(re.search(r"^\s*java.home = (.+)$", settings.stderr, re.M)[1])
java, javac = str(home / "bin/java"), str(home / "bin/javac")
commands = []


def run(name, args, data=None, expected=0, env=None):
    result = subprocess.run(args, input=data, capture_output=True, text=True, cwd=work,
                            timeout=90, env=env)
    (audit / f"{name}.stdout").write_text(result.stdout)
    (audit / f"{name}.stderr").write_text(result.stderr)
    commands.append({"name": name, "argv": args, "exit": result.returncode})
    assert result.returncode == expected, (name, result.returncode, result.stderr[:2000])
    return result


def cli(name, args, **kwargs):
    return run(name, [java, "-jar", str(jar), *args], **kwargs)


source = "public class Main { public static void main(String[] args) { System.out.println(42); } }"
main = "public class Main {\n    public static void main(String[] args) {\n        System.out.println(42);\n    }\n}\n\n"
path = work / "Main.java"
path.write_bytes(main.replace("\n", "\r\n").encode())
listing = json.loads(cli("listing-crlf-file", ["list-breakpoints", "-i", str(path), "--json"]).stdout)
assert len(listing) == 6 and listing[-1]["lineContent"] == "\r"
assert all(set(v) == {"lineNumber", "validBreakpoint", "lineContent", "file"} for v in listing)
assert all(v["file"] is None and v["lineContent"].endswith("\r") for v in listing)
stdin_listing = json.loads(cli("listing-crlf-stdin", ["list-breakpoints", "--json"], data=path.read_bytes().decode()).stdout)
assert len(stdin_listing) == 5 and all("\r" not in v["lineContent"] for v in stdin_listing)
bundle = "// --- Main.java ---\n" + main
single_bundle = json.loads(cli("listing-one-file-bundle", ["list-breakpoints", "--json"], data=bundle).stdout)
assert single_bundle[0]["lineContent"] == "// --- Main.java ---" and all(v["file"] is None for v in single_bundle)
multi = bundle + "// --- Helper.java ---\npublic class Helper {}\n"
multi_listing = json.loads(cli("listing-multi-file-bundle", ["list-breakpoints", "--json"], data=multi).stdout)
assert {v["file"] for v in multi_listing} == {"Main.java", "Helper.java"}
assert all(not v["lineContent"].startswith("// ---") for v in multi_listing)
terminal = cli("listing-terminal", ["list-breakpoints", "-i", str(path)]).stdout
assert "System.out.println(42)" in terminal

normal = json.loads(cli("phase-cli-completed", ["trace", "--format", "modern", "--result-envelope"], data=source).stdout)
assert normal["status"] == "completed" and normal["phase"] == "trace"
limited = json.loads(cli("phase-cli-source-files", ["trace", "--format", "modern", "--result-envelope", "--max-source-files", "1"], data=multi, expected=3).stdout)
assert limited["stopReason"] == "source_file_limit" and limited["phase"] == "compile"
jobs = [{"id": "parse-placeholder"}, {"id": "invalid", "source": source, "format": "bad"},
        {"id": "files", "source": multi, "format": "modern", "limits": {"sourceFiles": 1}},
        {"id": "ok", "source": source, "format": "modern", "limits": {"timeoutMillis": 5000}}]
batch_data = "{\n" + "\n".join(json.dumps(x) for x in jobs[1:]) + "\n"
responses = [json.loads(s) for s in cli("batch-status-and-phases", ["batch-trace", "--workers", "1"], data=batch_data).stdout.splitlines()]
assert len(responses) == 4
assert responses[0]["result"]["counters"] == {} and responses[1]["result"]["counters"] == {}
assert responses[2]["result"]["phase"] == "source" and responses[2]["result"]["stopReason"] == "source_file_limit"
assert responses[3]["result"]["phase"] == "serialize" and responses[3]["result"]["complete"]
core = {"snapshotsCaptured", "snapshotsRetained", "retainedBytes", "droppedSnapshots", "elapsedMillis"}
assert core <= responses[2]["result"]["counters"].keys()
assert core <= responses[3]["result"]["counters"].keys()
assert "guestExitCode" not in responses[3]["result"]["counters"]
assert cli("batch-empty", ["batch-trace"], data="").stdout == ""
assert "Batch trace failed:" in cli("batch-workers-error", ["batch-trace", "--workers", "0"], data="", expected=1).stderr
cli("batch-argument-error", ["batch-trace", "--workers", "bad"], data="", expected=2)
bad_env = dict(os.environ, JAVA_HOME=str(work / "missing-jdk"))
preflight = run("batch-preflight-error", [java, "-jar", str(jar), "batch-trace"], data="", expected=1, env=bad_env)
assert "JDK environment check failed" in preflight.stderr and "Batch trace failed:" not in preflight.stderr

null_source = """public class Main {
    public static void main(String[] args) {
        System.out.print("before");
        String value = null;
        System.out.print("after");
        System.out.println(value);
    }
}
"""
ordinary = json.loads(cli("null-modern-ordinary", ["trace", "--format", "modern", "--all-breakpoints"], data=null_source).stdout)
envelope = json.loads(cli("null-modern-envelope", ["trace", "--format", "modern", "--all-breakpoints", "--result-envelope"], data=null_source).stdout)
pytutor = json.loads(cli("null-pytutor", ["trace", "--all-breakpoints"], data=null_source).stdout)


def locals_at(payload, line):
    step = next(s for s in payload["steps"] if s["line"] == line and s.get("file", "").endswith("Main.java"))
    return next(f for f in step["callStack"] if f["methodName"] == "main")["locals"]


assert not any(v["name"] == "value" for v in locals_at(ordinary, 3))
ordinary_null = next(v for v in locals_at(ordinary, 5) if v["name"] == "value")
envelope_null = next(v for v in locals_at(envelope["trace"], 5) if v["name"] == "value")
assert "value" not in ordinary_null and envelope_null["value"] is None
assert any(f.get("encoded_locals", {}).get("value", "missing") is None for s in pytutor["trace"] for f in s["stack_to_render"])

api_source = r'''import cs1302.tracer.api.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import com.google.gson.Gson;
public class ApiProbe {
    public static void main(String[] args) throws Exception {
        Map<String,Object> report = new LinkedHashMap<>();
        var missing = Tracer.discoverBreakpoints("public class Main { int value; }");
        var ambiguous = Tracer.discoverBreakpoints("public class Main { public static void main(String[] a) {} public static void main() {} }");
        report.put("missingDiagnostics", missing.diagnostics().size());
        report.put("ambiguousDiagnostics", ambiguous.diagnostics().size());
        report.put("missingLocations", missing.breakpoints().size());
        report.put("ambiguousLocations", ambiguous.breakpoints().size());
        String source = "public class Main { public static void main(String[] a) { System.out.print(42); } }";
        var normal = Tracer.trace(TraceRequest.builder(source).format(TraceFormat.MODERN).build());
        report.put("normalPhase", normal.phase());
        String job = "{\"id\":\"late\",\"source\":\"public class Main { public static void main(String[] a) throws Exception { Thread.sleep(100); System.out.print(42); } }\",\"format\":\"modern\",\"limits\":{\"timeoutMillis\":5000}}\n";
        byte[] data = job.getBytes(StandardCharsets.UTF_8);
        boolean[] closed = {false, false};
        InputStream input = new InputStream() {
            int position;
            public int read() throws IOException {
                if (position == data.length) throw new IOException("input disconnected");
                return data[position++] & 255;
            }
            public int read(byte[] b, int off, int len) throws IOException {
                if (position == data.length) throw new IOException("input disconnected");
                int n = Math.min(len, data.length - position);
                System.arraycopy(data, position, b, off, n); position += n; return n;
            }
            public void close() { closed[0] = true; }
        };
        StringWriter output = new StringWriter() { public void close() { closed[1] = true; } };
        boolean failed = false;
        try (var tracer = BatchTracer.builder().workers(1).maxJobsPerWorker(1).maxInFlight(4).build()) {
            try { tracer.processStream(input, output); }
            catch (IOException expected) { failed = true; }
        }
        report.put("inputFailureReported", failed);
        report.put("responseAfterFailure", output.toString());
        report.put("inputClosed", closed[0]); report.put("writerClosed", closed[1]);
        System.out.println(new Gson().toJson(report));
    }
}
'''
(work / "ApiProbe.java").write_text(api_source)
run("api-compile", [javac, "--release", "21", "-cp", str(jar), "ApiProbe.java"])
api = json.loads(run("api-contracts", [java, "-cp", os.pathsep.join([str(work), str(jar)]), "ApiProbe"]).stdout)
assert api["missingDiagnostics"] and api["ambiguousDiagnostics"]
assert api["missingLocations"] == api["ambiguousLocations"] == 0
assert api["normalPhase"] == "serialize" and api["inputFailureReported"]
assert not api["inputClosed"] and not api["writerClosed"]
late = json.loads(api["responseAfterFailure"])
assert late["id"] == "late" and late["result"]["complete"]

summary = {"commands": commands, "listing": {"fileRows": len(listing), "stdinRows": len(stdin_listing),
           "oneFileBundleIncludesDelimiter": True, "multiFilePaths": sorted({x["file"] for x in multi_listing})},
           "phases": {"cliCompleted": normal["phase"], "cliSourceFileLimit": limited["phase"],
                      "batchCompleted": responses[3]["result"]["phase"], "batchSourceFileLimit": responses[2]["result"]["phase"]},
           "nullVariables": {"ordinary": ordinary_null, "envelope": envelope_null, "pytutorNull": True},
           "api": api, "jarSha256": hashlib.sha256(jar.read_bytes()).hexdigest()}
(audit / "contract-probes.json").write_text(json.dumps(summary, indent=2) + "\n")
print(json.dumps({"commandsPassed": len(commands), "work": str(work), "phases": summary["phases"]}, indent=2))

