"""Verify the documented multi-file basename-fallback limitation."""

import hashlib
import json
import subprocess
from pathlib import Path

root = Path.cwd()
audit = root / "target/audit/next-pass"
a = """package a;
public class Main {
    public static void main(String[] args) {
        int value = 1;
        System.out.println(value);
    }
}
"""
b = """package b;
public class Main {


    public static void helper() {
        System.out.println(2);
    }
}
"""
records = []
for label, prefix in [("exact", ""), ("prefixed", "src/")]:
    source = f"// --- {prefix}a/Main.java ---\n{a}// --- {prefix}b/Main.java ---\n{b}"
    command = ["java", "-jar", str(root / "target/code-tracer.jar"), "list-breakpoints", "--json"]
    run = subprocess.run(command, cwd=audit, input=source, capture_output=True, text=True, timeout=60)
    (audit / ("listing-paths-" + label + ".stdout")).write_text(run.stdout)
    (audit / ("listing-paths-" + label + ".stderr")).write_text(run.stderr)
    assert run.returncode == 0, run.stderr
    entries = json.loads(run.stdout)
    lines = {path: [x["lineNumber"] for x in entries if x["file"] == path and x["validBreakpoint"]]
             for path in sorted({x["file"] for x in entries})}
    records.append({"name": label, "argv": command, "exit": run.returncode, "source": source,
                    "validLines": lines})
exact, prefixed = [list(x["validLines"].values()) for x in records]
assert exact[0] != exact[1]
assert prefixed[0] == prefixed[1] and prefixed[1] != exact[1]
(audit / "listing-path-probes.json").write_text(json.dumps({"commands": records,
    "jarSha256": hashlib.sha256((root / "target/code-tracer.jar").read_bytes()).hexdigest(),
    "result": "Prefixed duplicate basenames reuse the first debug line table; package-relative logical paths select distinct correct tables."}, indent=2) + "\n")
print(json.dumps({"commandsPassed": len(records), "validLines": [x["validLines"] for x in records]}, indent=2))
